import{_ as e,o as r,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const d=JSON.parse('{"title":"服务器端渲染（SSR）概述","description":"在现代Web开发中， 服务器端渲染（Server Side Rendering, SSR） 已成为提升应用性能、SEO优化和用户体验的重要手段。使用React进行服务器端渲染，可以将React组件在服务器上预先渲染成HTML，然后将其发送给客户端，客户端再接管后续的交互。这种方法。","frontmatter":{"title":"服务器端渲染（SSR）概述","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","公司面试复盘"],"description":"在现代Web开发中， 服务器端渲染（Server Side Rendering, SSR） 已成为提升应用性能、SEO优化和用户体验的重要手段。使用React进行服务器端渲染，可以将React组件在服务器上预先渲染成HTML，然后将其发送给客户端，客户端再接管后续的交互。这种方法。","sidebarWeight":11,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/赢时胜/服务器端渲染（SSR）概述.md"},"headers":[],"relativePath":"posts/前端面试与实战/06-公司面试复盘/服务器端渲染（SSR）概述.md","filePath":"posts/前端面试与实战/06-公司面试复盘/服务器端渲染（SSR）概述.md"}'),n={name:"posts/前端面试与实战/06-公司面试复盘/服务器端渲染（SSR）概述.md"};function a(l,t,i,g,p,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<div><h1 id="服务器端渲染-ssr-概述" tabindex="-1">服务器端渲染（SSR）概述 <a class="header-anchor" href="#服务器端渲染-ssr-概述" aria-label="Permalink to &quot;服务器端渲染（SSR）概述&quot;">​</a></h1><blockquote><p>本节目标：理解“服务器端渲染（SSR）概述”的核心思路，并能把它用于实际开发或面试表达。 在现代Web开发中，<strong>服务器端渲染（Server-Side Rendering, SSR）</strong> 已成为提升应用性能、SEO优化和用户体验的重要手段。使用React进行服务器端渲染，可以将React组件在服务器上预先渲染成HTML，然后将其发送给客户端，客户端再接管后续的交互。这种方法结合了传统多页应用（MPA）和单页应用（SPA）的优势。本文将详细介绍如何使用React实现服务器端渲染，结合实际应用场景，涵盖其原理、实现步骤、优化方法以及常见的实操案例。</p></blockquote><p><strong>1. 服务器端渲染（SSR）概述</strong><strong>1.1 什么是服务器端渲染（SSR）？</strong> 服务器端渲染（SSR）是指在服务器上将React组件渲染成HTML字符串，然后将这些HTML发送到客户端浏览器。与之相对的是客户端渲染（Client-Side Rendering, CSR），即在客户端浏览器中通过JavaScript动态渲染React组件。 <strong>1.2 SSR的优势</strong></p><ol><li><strong>SEO友好</strong>： <ul><li>搜索引擎爬虫更容易抓取和索引预渲染的HTML内容，提升网站的搜索排名。</li></ul></li><li><strong>更快的首次内容渲染（FCP）</strong>： <ul><li>用户可以更快地看到页面内容，提升用户体验，特别是在网络较慢或设备性能较低的情况下。</li></ul></li><li><strong>更好的分享预览</strong>： <ul><li>社交媒体平台在分享链接时，可以直接抓取到完整的页面内容，生成丰富的预览信息。</li></ul></li><li><strong>性能优化</strong>： <ul><li>减少客户端的计算负担，适用于性能敏感的应用场景。</li></ul></li></ol><p><strong>1.3 SSR的劣势</strong></p><ol><li><strong>服务器负载增加</strong>： <ul><li>每个请求都需要在服务器上渲染页面，增加了服务器的计算负担。</li></ul></li><li><strong>复杂性增加</strong>： <ul><li>实现和维护SSR比CSR更为复杂，涉及服务器配置、数据预取等问题。</li></ul></li><li><strong>延迟与并发问题</strong>： <ul><li>高并发下，服务器的渲染能力可能成为瓶颈，影响响应时间。</li></ul></li></ol><p><strong>2. React实现SSR的原理</strong> React通过在服务器上使用ReactDOMServer库，将React组件渲染为HTML字符串。然后，将这个字符串嵌入到一个HTML模板中，发送给客户端。客户端接收到HTML后，通过“水合（hydrate）”过程将其转化为可交互的React应用。 <strong>2.1 渲染过程</strong></p><ol><li><strong>服务器渲染</strong>： <ul><li>使用ReactDOMServer.renderToString()或ReactDOMServer.renderToStaticMarkup()将React组件渲染为HTML字符串。</li></ul></li><li><strong>发送HTML</strong>： <ul><li>将渲染后的HTML字符串嵌入到HTML模板中，并发送给客户端浏览器。</li></ul></li><li><strong>客户端水合</strong>： <ul><li>客户端通过ReactDOM.hydrate()方法，将服务器渲染的HTML与React组件绑定，使其具有交互性。</li></ul></li></ol><p><strong>2.2 数据预取</strong> 在SSR过程中，通常需要在渲染React组件之前预取必要的数据。可以通过在服务器端获取数据，然后将数据传递给React组件，实现数据在服务器渲染时即被注入。</p><p><strong>3. React SSR的实现步骤</strong> 实现React SSR主要涉及以下步骤：</p><ol><li><strong>设置服务器环境</strong>： <ul><li>使用Node.js搭建服务器，处理HTTP请求。</li></ul></li><li><strong>配置Babel</strong>： <ul><li>使用Babel编译React和现代JavaScript代码，使其在Node.js环境中运行。</li></ul></li><li><strong>创建React组件</strong>： <ul><li>编写React组件，用于服务器渲染。</li></ul></li><li><strong>服务器端渲染逻辑</strong>： <ul><li>在服务器上渲染React组件，生成HTML字符串。</li></ul></li><li><strong>构建HTML模板</strong>： <ul><li>将渲染后的HTML字符串嵌入到HTML模板中，发送给客户端。</li></ul></li><li><strong>客户端水合</strong>： <ul><li>在客户端使用ReactDOM.hydrate()将预渲染的HTML转化为可交互的React应用。</li></ul></li></ol><p><strong>3.1 手动实现React SSR</strong> 以下是一个简单的React SSR实现示例： <strong>3.1.1 项目结构</strong> my-ssr-app/├── package.json├── server.js├── src/│ ├── App.js│ └── index.js├── public/│ └── index.html├── babel.config.js└── webpack.config.js <strong>3.1.2 安装依赖</strong> npm init -ynpm install react react-dom expressnpm install --save-dev @babel/core @babel/preset-env @babel/preset-react babel-loader webpack webpack-cli nodemon <strong>3.1.3 配置Babel</strong><strong>babel.config.js</strong> module.exports = { presets: [ &#39;@babel/preset-env&#39;, &#39;@babel/preset-react&#39; ]}; <strong>3.1.4 创建React组件</strong><strong>src/App.js</strong> import React from &#39;react&#39;; const App = ({ initialData }) =&gt; { return ( &lt;div&gt; &lt;h1&gt;服务器端渲染的React应用&lt;/h1&gt; &lt;p&gt;初始数据: {initialData}&lt;/p&gt; &lt;/div&gt; );}; export default App; <strong>3.1.5 设置服务器</strong><strong>server.js</strong> require(&#39;@babel/register&#39;)({ presets: [&#39;@babel/preset-env&#39;, &#39;@babel/preset-react&#39;]}); const path = require(&#39;path&#39;);const express = require(&#39;express&#39;);const fs = require(&#39;fs&#39;);const React = require(&#39;react&#39;);const ReactDOMServer = require(&#39;react-dom/server&#39;);const App = require(&#39;./src/App&#39;).default; const PORT = process.env.PORT || 3000;const app = express(); // 处理静态文件app.use(express.static(path.resolve(__dirname, &#39;public&#39;))); app.get(&#39;*&#39;, (req, res) =&gt; { // 模拟数据预取 const initialData = &quot;这是从服务器获取的数据&quot;; // 服务器渲染React组件 const appHtml = ReactDOMServer.renderToString( React.createElement(App, { initialData }) ); // 读取HTML模板 const indexFile = path.resolve(&#39;./public/index.html&#39;); fs.readFile(indexFile, &#39;utf8&#39;, (err, data) =&gt; { if (err) { console.error(&#39;读取HTML模板出错:&#39;, err); return res.status(500).send(&#39;内部服务器错误&#39;); } // 注入渲染后的HTML和初始数据 return res.send( data.replace(&#39;&lt;div id=&quot;root&quot;&gt;&lt;/div&gt;&#39;, <code>\\&lt;div id=&quot;root&quot;\\&gt;${appHtml}\\&lt;/div\\&gt; \\&lt;script\\&gt; window.__INITIAL_DATA__ = &quot;${initialData}&quot; \\&lt;/script\\&gt;</code>) ); });}); app.listen(PORT, () =&gt; { console.log(<code>服务器正在运行在 http://localhost:${PORT}</code>);}); <strong>3.1.6 创建HTML模板</strong><strong>public/index.html</strong> &lt;!DOCTYPE html&gt;&lt;html lang=&quot;en&quot;&gt;&lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;title&gt;React SSR 示例&lt;/title&gt;&lt;/head&gt;&lt;body&gt; &lt;div id=&quot;root&quot;&gt;&lt;/div&gt; &lt;script src=&quot;bundle.js&quot;&gt;&lt;/script&gt;&lt;/body&gt;&lt;/html&gt; <strong>3.1.7 客户端入口</strong><strong>src/index.js</strong> import React from &#39;react&#39;;import ReactDOM from &#39;react-dom&#39;;import App from &#39;./App&#39;; const initialData = window.<strong>INITIAL_DATA</strong>; ReactDOM.hydrate( &lt;App initialData={initialData} /&gt;, document.getElementById(&#39;root&#39;)); <strong>3.1.8 配置Webpack</strong><strong>webpack.config.js</strong> const path = require(&#39;path&#39;); module.exports = { entry: &#39;./src/index.js&#39;, output: { path: path.resolve(__dirname, &#39;public&#39;), filename: &#39;bundle.js&#39; }, module: { rules: [ { test: /.js$/, exclude: /node_modules/, use: { loader: &#39;babel-loader&#39; } } ] }, mode: &#39;development&#39;}; <strong>3.1.9 添加启动脚本</strong><strong>package.json</strong> { &quot;name&quot;: &quot;my-ssr-app&quot;, &quot;version&quot;: &quot;1.0.0&quot;, &quot;main&quot;: &quot;server.js&quot;, &quot;scripts&quot;: { &quot;build&quot;: &quot;webpack&quot;, &quot;start&quot;: &quot;nodemon server.js --exec babel-node&quot; }, &quot;dependencies&quot;: { &quot;express&quot;: &quot;^4.17.1&quot;, &quot;react&quot;: &quot;^17.0.2&quot;, &quot;react-dom&quot;: &quot;^17.0.2&quot; }, &quot;devDependencies&quot;: { &quot;@babel/core&quot;: &quot;^7.14.6&quot;, &quot;@babel/node&quot;: &quot;^7.14.5&quot;, &quot;@babel/preset-env&quot;: &quot;^7.14.7&quot;, &quot;@babel/preset-react&quot;: &quot;^7.14.5&quot;, &quot;babel-loader&quot;: &quot;^8.2.2&quot;, &quot;nodemon&quot;: &quot;^2.0.7&quot;, &quot;webpack&quot;: &quot;^5.38.1&quot;, &quot;webpack-cli&quot;: &quot;^4.7.2&quot; }} <strong>3.1.10 构建和运行</strong></p><h1 id="构建客户端代码npm-run-build" tabindex="-1">构建客户端代码npm run build <a class="header-anchor" href="#构建客户端代码npm-run-build" aria-label="Permalink to &quot;构建客户端代码npm run build&quot;">​</a></h1><h1 id="启动服务器npm-run-start" tabindex="-1">启动服务器npm run start <a class="header-anchor" href="#启动服务器npm-run-start" aria-label="Permalink to &quot;启动服务器npm run start&quot;">​</a></h1><p>访问 <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>，您将看到服务器渲染的React应用，并且浏览器控制台中没有React警告，表明水合成功。 <strong>3.2 使用Next.js实现React SSR</strong> 虽然手动实现SSR可以帮助开发者理解其原理，但在实际项目中，使用成熟的框架如<strong>Next.js</strong>会更为高效和便捷。Next.js提供了开箱即用的SSR支持，自动处理路由、数据预取、代码分割等功能。 <strong>3.2.1 创建Next.js项目</strong> npx create-next-app my-next-ssr-appcd my-next-ssr-appnpm run dev <strong>3.2.2 创建页面组件</strong> Next.js使用pages目录中的文件自动生成路由，支持服务器端渲染。 <strong>pages/index.js</strong> import React from &#39;react&#39;; const Home = ({ initialData }) =&gt; { return ( &lt;div&gt; &lt;h1&gt;Next.js SSR 示例&lt;/h1&gt; &lt;p&gt;初始数据: {initialData}&lt;/p&gt; &lt;/div&gt; );}; export async function getServerSideProps() { // 模拟数据预取 const initialData = &quot;这是从服务器获取的数据&quot;; return { props: { initialData } };} export default Home; 在上述示例中，getServerSideProps是一个Next.js提供的函数，用于在服务器端预取数据并将其作为props传递给组件。 <strong>3.2.3 启动和访问</strong> npm run dev 访问 <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>，即可看到服务器渲染的页面，初始数据已注入。</p><p><strong>4. 数据预取与同步</strong> 在SSR中，数据预取是关键步骤。需要在服务器端获取必要的数据，然后将其注入到React组件中，确保页面在首次渲染时即包含所需的数据。 <strong>4.1 手动实现数据预取</strong> 在手动SSR实现中，可以在服务器渲染之前通过API调用或其他方式获取数据，并将数据传递给React组件。 <strong>示例：</strong> app.get(&#39;*&#39;, async (req, res) =&gt; { try { // 预取数据 const response = await fetch(&#39;<a href="https://api.example.com/data" target="_blank" rel="noreferrer">https://api.example.com/data</a>&#39;); const data = await response.json(); // 服务器渲染React组件 const appHtml = ReactDOMServer.renderToString( React.createElement(App, { initialData: data }) ); // 注入HTML模板 const indexFile = path.resolve(&#39;./public/index.html&#39;); const html = fs.readFileSync(indexFile, &#39;utf8&#39;).replace( &#39;&lt;div id=&quot;root&quot;&gt;&lt;/div&gt;&#39;, <code>\\&lt;div id=&quot;root&quot;\\&gt;${appHtml}\\&lt;/div\\&gt; \\&lt;script\\&gt; window.__INITIAL_DATA__ = ${JSON.stringify(data)} \\&lt;/script\\&gt;</code> ); res.send(html); } catch (error) { console.error(&#39;数据预取失败:&#39;, error); res.status(500).send(&#39;内部服务器错误&#39;); }}); <strong>4.2 使用Next.js的数据预取</strong> Next.js通过getServerSideProps和getStaticProps简化了数据预取过程。 <strong>pages/about.js</strong> import React from &#39;react&#39;; const About = ({ aboutData }) =&gt; { return ( &lt;div&gt; &lt;h1&gt;关于我们&lt;/h1&gt; &lt;p&gt;{aboutData}&lt;/p&gt; &lt;/div&gt; );}; export async function getServerSideProps() { const response = await fetch(&#39;<a href="https://api.example.com/about" target="_blank" rel="noreferrer">https://api.example.com/about</a>&#39;); const aboutData = await response.text(); return { props: { aboutData } };} export default About; 在上述示例中，getServerSideProps在服务器端执行，预取数据并将其作为props传递给组件。</p><p><strong>5. 客户端水合</strong> **水合（Hydration）**是指将服务器渲染的静态HTML转化为可交互的React应用。客户端通过ReactDOM.hydrate()方法，实现这一过程。 <strong>5.1 手动SSR中的水合</strong> 在手动实现的SSR中，客户端入口文件通常使用ReactDOM.hydrate()而不是ReactDOM.render()。 <strong>src/index.js</strong> import React from &#39;react&#39;;import ReactDOM from &#39;react-dom&#39;;import App from &#39;./App&#39;; const initialData = window.<strong>INITIAL_DATA</strong>; ReactDOM.hydrate( &lt;App initialData={initialData} /&gt;, document.getElementById(&#39;root&#39;)); <strong>5.2 Next.js中的水合</strong> Next.js自动处理水合过程，无需开发者手动调用hydrate。只需使用ReactDOM.hydrate()作为默认行为，确保页面在客户端正常工作。</p><p><strong>6. 优化SSR的性能</strong> 为了确保SSR的高效性，需考虑以下优化措施： <strong>6.1 缓存</strong></p><ul><li><strong>页面缓存</strong>： <ul><li>对静态页面或频繁访问的页面进行缓存，减少服务器渲染的频率。</li></ul></li><li><strong>数据缓存</strong>： <ul><li>缓存API响应数据，避免重复请求，提高响应速度。</li></ul></li></ul><p><strong>示例：使用内存缓存</strong> const cache = {}; app.get(&#39;*&#39;, async (req, res) =&gt; { const cacheKey = req.url; if (cache[cacheKey]) { return res.send(cache[cacheKey]); } // 数据预取和渲染逻辑 const html = await renderPage(req); cache[cacheKey] = html; res.send(html);}); <strong>6.2 分片渲染</strong> 将应用拆分为多个独立渲染的部分，按需渲染，提高整体性能。 <strong>6.3 代码分割</strong> 通过代码分割（Code Splitting）减少首次加载的JavaScript体积，提高页面加载速度。 <strong>示例：使用React.lazy和Suspense</strong> import React, { Suspense, lazy } from &#39;react&#39;;import ReactDOM from &#39;react-dom&#39;; const LazyComponent = lazy(() =&gt; import(&#39;./LazyComponent&#39;)); ReactDOM.hydrate( &lt;Suspense fallback={&lt;div&gt;加载中...&lt;/div&gt;}&gt; &lt;LazyComponent /&gt; &lt;/Suspense&gt;, document.getElementById(&#39;root&#39;)); <strong>6.4 服务器性能优化</strong></p><ul><li><strong>使用高性能服务器</strong>： <ul><li>选择高效的Node.js服务器，优化服务器配置，提升渲染速度。</li></ul></li><li><strong>异步渲染</strong>： <ul><li>使用异步数据预取和渲染，提高并发处理能力。</li></ul></li></ul><p><strong>6.5 静态资源优化</strong></p><ul><li><strong>压缩和缩小</strong>： <ul><li>压缩JavaScript和CSS文件，减少传输体积。</li></ul></li><li><strong>使用CDN</strong>： <ul><li>将静态资源部署到内容分发网络（CDN），缩短资源加载时间。</li></ul></li></ul><p><strong>7. 实际应用场景中的SSR优势</strong><strong>7.1 内容丰富的博客和新闻网站</strong> 这些网站依赖于搜索引擎流量，SSR能够确保搜索引擎爬虫能够正确抓取和索引内容，提高网站的SEO表现。 <strong>示例：Next.js博客</strong> Next.js非常适合构建博客，支持静态生成（Static Generation）和服务器端渲染，结合Markdown文件，实现高效内容管理和渲染。 <strong>7.2 电子商务平台</strong> 电子商务网站需要快速加载以提升用户体验，特别是在移动设备上。SSR可以显著提升首次渲染速度，减少用户等待时间。 <strong>示例：React + Redux SSR电子商务应用</strong> 结合Redux进行状态管理，通过服务器预取购物车数据、商品列表等，快速呈现完整页面。 <strong>7.3 社交媒体和实时应用</strong> 社交媒体平台需要处理大量的动态内容和用户交互。SSR可以提升初始页面加载速度，提升用户体验。 <strong>示例：React SSR + WebSocket</strong> 结合SSR和WebSocket，实现初始内容的快速加载和实时更新，提供流畅的用户体验。 <strong>7.4 企业级仪表盘和管理系统</strong> 这些应用通常需要展示大量的数据和复杂的交互。SSR可以优化数据加载和渲染，提高整体性能和响应速度。 <strong>示例：React SSR + GraphQL</strong> 使用GraphQL进行高效的数据查询，通过SSR预取关键数据，快速渲染仪表盘。</p><p><strong>8. 实操建议与最佳实践</strong><strong>8.1 使用成熟的框架</strong> 尽量使用成熟的SSR框架如<strong>Next.js</strong>，它提供了开箱即用的SSR支持，简化了配置和开发过程，同时拥有活跃的社区和丰富的插件生态。 <strong>8.2 处理数据预取</strong> 确保在服务器渲染之前预取所有必要的数据，避免在客户端进行重复请求。可以使用getServerSideProps（Next.js）或手动在服务器上预取数据。 <strong>8.3 优化初始加载</strong> 通过代码分割、懒加载和资源压缩等手段，减少首次加载的JavaScript和CSS体积，提升页面加载速度。 <strong>8.4 管理状态</strong> 结合状态管理工具如<strong>Redux</strong>或<strong>MobX</strong>，在服务器和客户端之间同步状态，确保一致性和可预测性。 <strong>8.5 实现缓存策略</strong> 结合页面缓存和数据缓存，减少服务器的渲染负担，提升响应速度。可以使用内存缓存、Redis等缓存工具。 <strong>8.6 监控和日志</strong> 在生产环境中，监控SSR的性能和错误，及时发现和解决问题。可以使用日志记录工具和性能监控服务。 <strong>8.7 考虑渐进增强</strong> 在实现SSR的同时，保持应用在没有JavaScript支持的情况下仍然可用，实现渐进增强，提升应用的兼容性和可访问性。</p><p><strong>9. 示例项目：使用Next.js实现SSR</strong> 以下是一个使用Next.js构建的简单SSR项目示例，展示了数据预取和页面渲染的过程。 <strong>9.1 创建Next.js项目</strong> npx create-next-app my-next-ssr-appcd my-next-ssr-appnpm run dev <strong>9.2 编写首页组件</strong><strong>pages/index.js</strong> import React from &#39;react&#39;; const Home = ({ posts }) =&gt; { return ( &lt;div&gt; &lt;h1&gt;Next.js SSR 示例&lt;/h1&gt; &lt;ul&gt; {posts.map(post =&gt; ( &lt;li key={post.id}&gt;{post.title}&lt;/li&gt; ))} &lt;/ul&gt; &lt;/div&gt; );}; export async function getServerSideProps() { // 从API获取数据 const res = await fetch(&#39;<a href="https://jsonplaceholder.typicode.com/posts" target="_blank" rel="noreferrer">https://jsonplaceholder.typicode.com/posts</a>&#39;); const posts = await res.json(); return { props: { posts: posts.slice(0, 10) // 只取前10条 } };} export default Home; <strong>9.3 运行并访问</strong> 启动开发服务器： npm run dev 访问 <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>，您将看到服务器端渲染的页面，包含预先加载的帖子列表。</p><p><strong>10. 总结</strong> 使用React实现服务器端渲染（SSR）是一种有效提升应用性能、SEO表现和用户体验的技术手段。通过在服务器上预先渲染React组件，可以确保页面内容的快速加载和搜索引擎的良好抓取。同时，结合成熟的框架如Next.js，可以大幅简化SSR的实现过程，提升开发效率和代码维护性。 在实际项目中，选择是否使用SSR应基于具体需求，如SEO要求、首次加载性能、应用复杂度和开发资源等因素。对于内容丰富、SEO敏感的应用，SSR无疑是一个强有力的工具。而对于高度动态和交互密集的应用，可以结合SSR和CSR的优势，实现更佳的用户体验。 通过深入理解SSR的原理和实践方法，开发者可以更好地利用React的强大功能，构建高效、可维护和性能优越的现代Web应用。 &gt; 来自 &lt;<a href="https://chatgpt.com/c/677e0e2c-71c4-8004-b340-26e0f8bae043" target="_blank" rel="noreferrer">https://chatgpt.com/c/677e0e2c-71c4-8004-b340-26e0f8bae043</a>&gt;</p></div>',1)])])}const S=e(n,[["render",a]]);export{d as __pageData,S as default};
